#!/usr/bin/env python3
"""Materialize Relation Kind/v2 and Typed Relation/v2 against the 40-axis model."""
from __future__ import annotations
import copy,hashlib,importlib.util,json
from pathlib import Path
ROOT=Path(__file__).resolve().parent;LAB=ROOT.parents[3]
MODEL=LAB/'authority/relation-kinds/candidates/0005-definition-complete-extension/model.json';EXAMPLES=LAB/'authority/relation-kinds/candidates/0005-definition-complete-extension/examples.json'
OLD=LAB/'authority/relation-kinds/candidates/0003-admission-ready-instances/build.py';RK1=LAB/'authority/artifact-types/relation-kind/v1';TR1=LAB/'authority/artifact-types/typed-relation/v1';RK2=LAB/'authority/artifact-types/relation-kind/v2';TR2=LAB/'authority/artifact-types/typed-relation/v2'
def load(p):return json.loads(Path(p).read_text(encoding='utf-8'))
def sha(p):return hashlib.sha256(Path(p).read_bytes()).hexdigest()
