def main():
 spec=importlib.util.spec_from_file_location('legacy_relation_builder',OLD);b=importlib.util.module_from_spec(spec);assert spec and spec.loader;spec.loader.exec_module(b);b.ROOT=ROOT;b.LAB=LAB
 model=load(MODEL);examples=load(EXAMPLES);entries=model['entries'];rk_schema=b.relation_kind_schema();tr_schema=b.typed_relation_schema(entries,examples)
 rk_art=b.artifact_v2(RK1,RK2,rk_schema,'relation-kind','Relation Kind/v2 is the complete closed 40-axis contract: one question, operational effect, exact ordered endpoint pairs, exact qualifier schema, forbidden inferences, and preserved lineage.',['complete semantic-axis payload','closed endpoint pairs','closed qualifier contract','forbidden inference preservation','40 instance validation'])
 tr_art=b.artifact_v2(TR1,TR2,tr_schema,'typed-relation','Typed Relation/v2 records one independently identified global connection whose Relation Kind fixes the exact ordered endpoint pair and closed qualifier object.',['known Relation Kind','exact ordered endpoint pair','exact qualifier set','endpoint revision binding','40 example validation'])
 rk_records={};tr_records={};admit=[]
 for e in entries:
  rid=e['relation_kind_id'];slug=rid.removeprefix('relation.');rk=b.relation_instance(e,examples[rid]);tr=b.typed_instance(e,examples[rid]);rk_records[rid]=rk;tr_records[rid]=tr;rp=ROOT/f'instances/relation-kinds/{slug}.json';tp=ROOT/f'instances/typed-relations/{slug}.json';dump(rp,rk);dump(tp,tr);admit.append({'relation_kind_id':rid,'instance_ref':rk['node_id'],'instance_path':str(rp.relative_to(LAB)),'instance_sha256':sha(rp),'relation_kind_carrier_ref':'cal.artifact-type.relation-kind/v2','typed_relation_example_path':str(tp.relative_to(LAB)),'typed_relation_example_sha256':sha(tp),'admission_action':'admit-relation-kind-instance','typed_relation_example_admission':'excluded'})
 rv=rk_records['relation.member-of'];tv=tr_records['relation.realizes'];
 rbad=copy.deepcopy(rv);del rbad['payload']['unique_question'];rextra=copy.deepcopy(rv);rextra['payload']['undeclared']=True;rwild=copy.deepcopy(rv);rwild['payload']['allowed_endpoint_pairs'][0]['source_kind']='*';rauth=copy.deepcopy(rv);rauth['authority_effect']='admit';b.write_package_support(RK2,rv,{'missing-qualifier':rbad,'extra-qualifier':rextra,'undeclared-pair':rwild,'authority':rauth})
 tmissing=copy.deepcopy(tv);tmissing['payload']['qualifiers'].pop(next(iter(tmissing['payload']['qualifiers'])));textra=copy.deepcopy(tv);textra['payload']['qualifiers']['undeclared_axis']='invalid';tpair=copy.deepcopy(tv);tpair['payload']['source']['kind']='product';tauth=copy.deepcopy(tv);tauth['authority_effect']='admit';b.write_package_support(TR2,tv,{'missing-qualifier':tmissing,'extra-qualifier':textra,'undeclared-pair':tpair,'authority':tauth})
 for package in (RK2,TR2):
  (package/'validate.py').write_text("#!/usr/bin/env python3\nfrom pathlib import Path\nimport subprocess,sys\nR=Path(__file__).resolve().parent;T=R.parents[2]/'relation-kinds/candidates/0006-definition-complete-instances/validate.py'\nraise SystemExit(subprocess.run([sys.executable,str(T),'--package',str(R)]).returncode)\n")
 carriers={'schema_version':'cyberalchemy-lab-definition-complete-relation-carriers/v1','status':'candidate-materialized','authority_effect':'none','entries':[{'artifact_type_ref':rk_art['artifact_type_ref'],'artifact_path':str((RK2/'artifact.json').relative_to(LAB)),'artifact_sha256':sha(RK2/'artifact.json'),'schema_path':str((RK2/'schema.json').relative_to(LAB)),'schema_sha256':sha(RK2/'schema.json')},{'artifact_type_ref':tr_art['artifact_type_ref'],'artifact_path':str((TR2/'artifact.json').relative_to(LAB)),'artifact_sha256':sha(TR2/'artifact.json'),'schema_path':str((TR2/'schema.json').relative_to(LAB)),'schema_sha256':sha(TR2/'schema.json')}]};dump(ROOT/'carrier-postimages.json',carriers)
 dump(ROOT/'relation-kind-instances.json',{'schema_version':'cyberalchemy-lab-relation-kind-instance-set/v3','status':'candidate-unadmitted','authority_effect':'none','count':len(rk_records),'entries':list(rk_records.values())});dump(ROOT/'typed-relation-examples.json',{'schema_version':'cyberalchemy-lab-typed-relation-example-set/v3','status':'candidate-unadmitted','authority_effect':'none','count':len(tr_records),'entries':list(tr_records.values())});dump(ROOT/'relation-kind-admission-manifest.json',{'schema_version':'cyberalchemy-lab-relation-kind-admission-manifest/v1','status':'proposal-only','authority_effect':'none','count':len(admit),'entries':admit,'typed_relation_instances_to_admit':0,'claim_ceiling':'This binds 40 exact candidate Relation Kind records. Typed Relation examples are excluded. It admits nothing.'})
 candidate={'schema_version':'cyberalchemy-lab-definition-complete-relation-materialization/v1','candidate_id':'CAL-DEFINITION-COMPLETE-RELATION-INSTANCES-0006','status':'candidate-owner-review-open','authority_effect':'none','inputs':{'model':{'path':str(MODEL.relative_to(LAB)),'sha256':sha(MODEL)},'examples':{'path':str(EXAMPLES.relative_to(LAB)),'sha256':sha(EXAMPLES)}},'counts':{'relation_kinds':len(entries),'typed_relation_examples':len(entries),'exact_endpoint_pairs':model['counts']['declared_endpoint_pairs'],'carrier_v2_candidates':2,'typed_relation_instances_to_admit':0},'claim_ceiling':'This materializes complete candidate carriers, Relation Kind records, and excluded Typed Relation examples. It admits nothing.'};dump(ROOT/'candidate.json',candidate)
 lines=['<!-- GENERATED FILE: canonical data is relation-kind-instances.json. -->','','# Definition-complete Relation Kind instances','',f"- Relation Kinds: `{len(entries)}`",f"- Exact ordered endpoint pairs: `{model['counts']['declared_endpoint_pairs']}`",f"- Typed Relation examples excluded from admission: `{len(entries)}`",'- Authority effect: `none`','']
 for e in entries:lines += [f"## `{e['relation_kind_id']}`",'',e['unique_question'],'',f"Required qualifiers: `{', '.join(e['required_qualifier_axes'])}`",'',f"Exact pairs: `{len(e['allowed_endpoint_pairs'])}`",'']
 lines += ['## Claim ceiling','',candidate['claim_ceiling'],''];(ROOT/'RELATION-KINDS.md').write_text('\n'.join(lines),encoding='utf-8')
if __name__=='__main__':main()
